498	/**
499	 * `text` in alternating runs of prose and fenced code, by CommonMark's rule:
500	 * a fence opens with at least three backticks or tildes (up to three spaces of
501	 * indent) and closes with the same character, at least as many of them, and
502	 * nothing else on the line. A fence never closed runs to the end of the text,
503	 * which is the safe direction -- the rest is evidence rather than bookkeeping.
504	 *
505	 * Backtick fences may not carry backticks in their info string; that rule is what
506	 * keeps an inline `` `a` `` inside a sentence from opening a block.
507	 */
508	function fenceSegments(text: string): TextSegment[] {
509	  const lines = text.match(/[^\n]*\n|[^\n]+$/g) ?? [];
510	  const segments: TextSegment[] = [];
511	  let open: { char: string; length: number } | null = null;
512	  let current: TextSegment = { text: "", code: false };
513	
514	  for (const line of lines) {
515	    const bare = line.replace(/\r?\n$/, "");
516	    const fence = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(bare);
517	    if (open === null) {
518	      const opens = fence !== null && (fence[1]![0] !== "`" || !fence[2]!.includes("`"));
519	      if (opens) {
520	        if (current.text) segments.push(current);
521	        open = { char: fence[1]![0]!, length: fence[1]!.length };
522	        current = { text: line, code: true };
523	      } else {
524	        current.text += line;
525	      }
526	      continue;
527	    }
528	
529	    current.text += line;
530	    if (fence && fence[1]![0] === open.char && fence[1]!.length >= open.length && fence[2]!.trim() === "") {
531	      segments.push(current);
532	      current = { text: "", code: false };
533	      open = null;
534	    }
535	  }
536	
537	  if (current.text) segments.push(current);
538	  return segments;
539	}
